insert into public.recipes
    (slug, title, emoji, description, total_minutes, difficulty, servings, published,
     source_name, source_url, license_name, attribution, modified_from_source)
values
    ('wikibooks_easy_wedding_soup', 'Easy Wedding Soup', '🥣', 'Easy wedding soup is a simple variation on Italian wedding soup that requires only four ingredients and water.', 20, 'Easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AEasy+Wedding+Soup&oldid=4518395', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_corn_sticks', 'Corn Sticks', '🍳', 'A practical recipe for Corn Sticks, adapted from the Wikibooks Cookbook.', 60, 'Easy', 14, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACorn+Sticks&oldid=4595356', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_gozleme_turkish_flatbread', 'Gözleme (Turkish Flatbread)', '🍞', 'A modern variation is honey and banana served hot with a slice of lemon.', 60, 'Medium', 10, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AG%C3%B6zleme+%28Turkish+Flatbread%29&oldid=4503985', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 'Spinach Mushroom Pesto Spaghetti', '🍝', 'This spinach mushroom pesto spaghetti recipe is adapted from the YouTube channel Tasty.', 15, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASpinach+Mushroom+Pesto+Spaghetti&oldid=4610477', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_ambrosia_fruit_salad', 'Ambrosia Fruit Salad', '🥗', 'Below is one interpretation.', 65, 'Very easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AAmbrosia+Fruit+Salad&oldid=4630232', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_hake_in_herby_breadcrumbs', 'Hake in Herby Breadcrumbs', '🍞', 'Hake in herby breadcrumbs is a fairly simple way of serving hake, or any other white fish. It has a nice crunchy texture and subtle flavours from the herbs and pine nuts. It''s easily scalable. The details here are...', 25, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AHake+in+Herby+Breadcrumbs&oldid=4513512', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_risengrd', 'Risengrød', '🍚', 'Risengrød is part of the Nordic Christmas tradition as a dinner dish. It is simply rice boiled with milk and a little sugar to form porridge, and it is served warm with butter and cinnamon-sugar.', 90, 'Very easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ARisengr%C3%B8d&oldid=4597644', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_cornbread_i', 'Cornbread I', '🍞', 'Cornbread is a type of quick bread made of cornmeal and sometimes supplemented with wheat flour. Some variations may include whole corn kernels.', 45, 'Easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACornbread+I&oldid=4523344', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_spanish_potato_omelette', 'Spanish Potato Omelette', '🥔', 'This recipe is based on the translation of the Recipe in Spanish.', 20, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASpanish+Potato+Omelette&oldid=4500599', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 'Deep Fried Chiles Filled with Chickpea Flour (Mirchi Bhajji)', '🍚', 'Mirchi bhajji are fried stuffed peppers.', 30, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ADeep+Fried+Chiles+Filled+with+Chickpea+Flour+%28Mirchi+Bhajji%29&oldid=4506355', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_garlic_croutons_ii', 'Garlic Croutons II', '🍞', 'A practical recipe for Garlic Croutons II, adapted from the Wikibooks Cookbook.', 20, 'Very easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AGarlic+Croutons+II&oldid=4505423', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_hot_and_sour_soup', 'Hot and Sour Soup', '🥣', 'Hot and sour soup is a popular soup served at Chinese restaurants in the United States. This version tastes exactly like that served at various Chinese restaurants in California.', 20, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AHot+and+Sour+Soup&oldid=4518420', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 'Romanian Roasted Eggplant Spread II', '🍳', 'Salată de vinete (eggplant salad) is a common Romanian spread made with eggplants and onion. It is usually eaten with bread.', 15, 'Easy', 15, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ARomanian+Roasted+Eggplant+Spread+II&oldid=4505504', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_red_devils', 'Red Devils', '🍞', 'Red Devils are hot, open faced sandwiches. They are a great dinner or lunch. They include all the major food groups and taste great. Their ease of preparation makes them suitable for people on the move and the recipe...', 20, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ARed+Devils&oldid=4518276', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true)
on conflict (slug) do update set
    title = excluded.title,
    emoji = excluded.emoji,
    description = excluded.description,
    total_minutes = excluded.total_minutes,
    difficulty = excluded.difficulty,
    servings = excluded.servings,
    published = excluded.published,
    source_name = excluded.source_name,
    source_url = excluded.source_url,
    license_name = excluded.license_name,
    attribution = excluded.attribution,
    modified_from_source = excluded.modified_from_source,
    updated_at = now();

