insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
    ('wikibooks_easy_wedding_soup', 1, 'Bring broth and water to boil in 4-quart saucepan.'),
    ('wikibooks_easy_wedding_soup', 2, 'Add frozen spinach.'),
    ('wikibooks_easy_wedding_soup', 3, 'Cut sausage into small pieces.'),
    ('wikibooks_easy_wedding_soup', 4, 'Add sausage and acini di pepe to soup.'),
    ('wikibooks_easy_wedding_soup', 5, 'Bring back to boil, and allow to boil for 10 minutes.'),
    ('wikibooks_corn_sticks', 1, 'Preheat oven to 425°F (220°C). Grease a corn stick pan well, and preheat inside the oven. Cast iron works best.'),
    ('wikibooks_corn_sticks', 2, 'Combine corn meal, flour, baking powder, salt, and sugar in a large mixing bowl.'),
    ('wikibooks_corn_sticks', 3, 'Add egg, sugar, and shortening. Beat until fairly smooth (about 1 minute).'),
    ('wikibooks_corn_sticks', 4, 'Pour into the hot, well-greased cornstick pan.'),
    ('wikibooks_corn_sticks', 5, 'Bake for 15–20 minutes until golden brown. If corn is added to batter, increase time a little.'),
    ('wikibooks_corn_sticks', 6, 'Serve hot and buttered.'),
    ('wikibooks_gozleme_turkish_flatbread', 1, 'Sift flour in a large bowl, reserving 1 cup of flour.'),
    ('wikibooks_gozleme_turkish_flatbread', 2, 'Sprinkle with salt and mix. Make a well in the centre.'),
    ('wikibooks_gozleme_turkish_flatbread', 3, 'Combine yeast and sugar in a small bowl. Stir in ¼ cup warm water.'),
    ('wikibooks_gozleme_turkish_flatbread', 4, 'Pour the liquid into the well in the centre of the flour.'),
    ('wikibooks_gozleme_turkish_flatbread', 5, 'Cover yeast with some flour. Let stand for 10 minutes to rise.'),
    ('wikibooks_gozleme_turkish_flatbread', 6, 'Stir in remaining liquid, blending thoroughly. Knead for 5 minutes to form a medium-soft dough.'),
    ('wikibooks_gozleme_turkish_flatbread', 7, 'Cover and let rise in a warm place for 1 hour or until doubled in bulk.'),
    ('wikibooks_gozleme_turkish_flatbread', 8, 'Place dough on lightly floured board. Divide into 10 portions with floured hands.'),
    ('wikibooks_gozleme_turkish_flatbread', 9, 'Shape portions into balls; roll each ball out with rolling pin into a 5 mm thick rectangle. Brush with oil.'),
    ('wikibooks_gozleme_turkish_flatbread', 10, 'Fold opposite edges over, bringing edges together in centre.'),
    ('wikibooks_gozleme_turkish_flatbread', 11, 'Spread filling over half of pastry. Then fold other half over filling, shaping into an oblong.'),
    ('wikibooks_gozleme_turkish_flatbread', 12, 'Seal edges well, pressing slightly.'),
    ('wikibooks_gozleme_turkish_flatbread', 13, 'Heat griddle or a cast iron skillet.'),
    ('wikibooks_gozleme_turkish_flatbread', 14, 'Grease with butter and place gözleme on griddle.'),
    ('wikibooks_gozleme_turkish_flatbread', 15, 'Brown on both sides.'),
    ('wikibooks_gozleme_turkish_flatbread', 16, 'Serve hot with ayran.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 1, 'Boil the spaghetti in water until al dente.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 2, 'Meanwhile, heat the oil in a pan over a medium heat.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 3, 'Cook the spinach for 5 minutes until it is wilted.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 4, 'Add the mushrooms, salt, and pepper and cook for a further 3 minutes, stirring occasionally.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 5, 'Stir in the pesto and cheese and cook for 2 minutes.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 6, 'Drain the pasta in a colander and stir into the sauce.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 7, 'Divide the pasta between 4 plates and serve.'),
    ('wikibooks_spinach_mushroom_pesto_spaghetti', 8, 'To serve, sprinkle with some extra cheese.'),
    ('wikibooks_ambrosia_fruit_salad', 1, 'Mix the mandarin oranges, pineapple, and grapes in a large bowl.'),
    ('wikibooks_ambrosia_fruit_salad', 2, 'Fold in the whipped cream, sour cream, and marshmallows.'),
    ('wikibooks_ambrosia_fruit_salad', 3, 'Chill for at least an hour.'),
    ('wikibooks_ambrosia_fruit_salad', 4, 'Stir again before serving.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 1, 'Preheat the oven to gas mark 4.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 2, 'Mix together the breadcrumb ingredients in a food processor, adding the oil last. It should be a slightly moist mixture.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 3, 'Dip each hake fillet in beaten egg, then in the breadcrumb mix. Try to get the fillet evenly coated.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 4, 'Place each fillet in a gratin dish, drizzling a little oil on top.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 5, 'Bake in the oven for 20 minutes until the breadcrumbs are browned.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 6, 'Sprinkle some lemon juice on top.'),
    ('wikibooks_hake_in_herby_breadcrumbs', 7, 'Serve with a dressed salad.'),
    ('wikibooks_risengrd', 1, 'Bring water and rice to a boil in a deep pot. Boil the rice at steady heat and with active stirring for approximately 2 minutes.'),
    ('wikibooks_risengrd', 2, 'Add milk and return to a boil. Simmer over low heat, stirring actively for approximately 10 minutes.'),
    ('wikibooks_risengrd', 3, 'Put on lid and simmer for approximately 30 minutes, stirring often to prevent sticking.'),
    ('wikibooks_risengrd', 4, 'Test the porridge for thickness—if it seems too thin, simmer for another 5–10 minutes.'),
    ('wikibooks_risengrd', 5, 'Add salt.'),
    ('wikibooks_risengrd', 6, 'Combine sugar and cinnamon in a bowl or container.'),
    ('wikibooks_risengrd', 7, 'Serve porridge warm with cinnamon-sugar on top and a bit of butter in the middle.'),
    ('wikibooks_cornbread_i', 1, 'Preheat oven to . Grease an baking pan.'),
    ('wikibooks_cornbread_i', 2, 'Combine cornmeal, flour, baking powder, salt, and sugar in a large mixing bowl.'),
    ('wikibooks_cornbread_i', 3, 'Add egg, milk, and shortening.'),
    ('wikibooks_cornbread_i', 4, 'Beat until fairly smooth (about a minute).'),
    ('wikibooks_cornbread_i', 5, 'If using corn and/or onion, fold in these ingredients.'),
    ('wikibooks_cornbread_i', 6, 'Pour the mixture into the baking pan.'),
    ('wikibooks_cornbread_i', 7, 'Bake for 20–25 minutes or until a toothpick inserted in center comes out clean. If corn is added to batter, increase time by ~50%'),
    ('wikibooks_cornbread_i', 8, 'Serve hot!'),
    ('wikibooks_spanish_potato_omelette', 1, 'Peel the potatoes, wash them, and dry them with a cloth. Cut them into 1 cm cubes or 2 mm slices. Wash and dry them again. Add some salt to your taste and mix them.'),
    ('wikibooks_spanish_potato_omelette', 2, 'Heat the oil; when hot, fry the potatoes, but do not let them get brown. Once they''re done, drain the oil and store the potatoes.'),
    ('wikibooks_spanish_potato_omelette', 3, 'Dice or slice the onion; fry it until it is translucent.'),
    ('wikibooks_spanish_potato_omelette', 4, 'Beat the 8 eggs in a bowl with a small amount of salt until the mix is homogenous. Then, mix in the potatoes and the onion.'),
    ('wikibooks_spanish_potato_omelette', 5, 'Heat 3 tablespoons of olive oil in an empty pan – you can use the previous pan after removing most of the oil.'),
    ('wikibooks_spanish_potato_omelette', 6, 'Once the pan is hot, add the egg with the onion and the potatoes.'),
    ('wikibooks_spanish_potato_omelette', 7, 'After 7–8 minutes, the bottom part should be done. Put the dish over the pan and carefully turn it around so that the undone part rests on the dish. This is the most difficult step of the recipe. After that, put the pan on the fire again and slowly slide the mix into the pan to cook the other side.'),
    ('wikibooks_spanish_potato_omelette', 8, 'After a couple of additional minutes, it should be done and ready to serve.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 1, 'Slit 5–10 of the peppers, preferably the longest and fattest.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 2, 'Mix salt and gram flour. Stuff the slit peppers with this mixture, and keep aside for 15–20 minutes.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 3, 'Heat oil in a pan over medium heat.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 4, 'Mix all other dry ingredients. Dip each green pepper into this mixture gently to coat it.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 5, 'Deep fry in heated oil until golden brown.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 6, 'Drain on kitchen paper to remove excess oil.'),
    ('wikibooks_deep_fried_chiles_filled_with_chickpea_flour_mirchi_bhajji', 7, 'Serve hot with chutney or ketchup.'),
    ('wikibooks_garlic_croutons_ii', 1, 'Warm an 8-inch skillet over low heat while preparing bread. A minute before you are ready to cook, turn heat up to medium.'),
    ('wikibooks_garlic_croutons_ii', 2, 'Toss bread in a bowl with oil, salt, and garlic powder.'),
    ('wikibooks_garlic_croutons_ii', 3, 'Cook, stirring often, until crisp and golden brown (about 7 minutes).'),
    ('wikibooks_garlic_croutons_ii', 4, 'Use as a garnish for soups and salads.'),
    ('wikibooks_hot_and_sour_soup', 1, 'Bring chicken broth to a simmer in a 2-quart saucepan.'),
    ('wikibooks_hot_and_sour_soup', 2, 'Add soy sauce, shredded meat, mushrooms and garlic chili sauce. Simmer for 5 minutes.'),
    ('wikibooks_hot_and_sour_soup', 3, 'Add black pepper, white vinegar, bamboo shoots, tofu. Simmer for 5 minutes.'),
    ('wikibooks_hot_and_sour_soup', 4, 'Combine 3 tablespoons of cornstarch with 2 tablespoons of cold water in a cup. Stir until mixture is smooth. Add cornstarch mixture to soup and stir well.'),
    ('wikibooks_hot_and_sour_soup', 5, 'Simmer for 5 minutes until soup is thickened.'),
    ('wikibooks_hot_and_sour_soup', 6, 'Beat egg in a cup until yolk and white are combined. Pour beaten egg slowly, in a fine stream into soup. Stir soup several times, then wait 30 seconds.'),
    ('wikibooks_hot_and_sour_soup', 7, 'Add green onions and sesame oil to soup. Stir well and remove from heat.'),
    ('wikibooks_hot_and_sour_soup', 8, 'Serve hot.'),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 1, 'Roast the eggplants. This can be done in a variety of ways, but the flesh should be fully cooked and the skin should be burned and falling off easily. An effective method is to prick the eggplants and place them in a preheated 400 °F oven until the skin is charred and a fork easily pierces the vegetable all the way through.'),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 2, 'Skin the the eggplants—the skin should come off easily by hand. Use the back of a table knife to scrape off any residual eggplant from the skin once the skin is removed—this portion of eggplant retains the smoky flavor and should not be discarded.'),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 3, 'Finely chop or blend the eggplant flesh. The consistency should be smooth, like a purée.'),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 4, 'Transfer the eggplant to a bowl, and mix in the other ingredients. The amounts can be adjusted for taste.'),
    ('wikibooks_romanian_roasted_eggplant_spread_ii', 5, 'Chill in the fridge until serving.'),
    ('wikibooks_red_devils', 1, 'Place bacon in a sheet pan.'),
    ('wikibooks_red_devils', 2, 'Set the broiler to ''low''.'),
    ('wikibooks_red_devils', 3, 'Pre-cook the bacon under the broiler until it is about halfway done.'),
    ('wikibooks_red_devils', 4, 'While bacon cooks, place white bread on a sheet, one slice per diner.'),
    ('wikibooks_red_devils', 5, 'Place a slice of American cheese on each slice of bread.'),
    ('wikibooks_red_devils', 6, 'Place the tomato slices on each sandwich'),
    ('wikibooks_red_devils', 7, 'Sprinkle a small amount of onion onto each sandwich.'),
    ('wikibooks_red_devils', 8, 'Place a strip of half-cooked bacon on each sandwich.'),
    ('wikibooks_red_devils', 9, 'Place the cookie sheet under broiler, set to maximum temperature, and broil for approximately 3–4 minutes. You must check on them often to prevent burning.'),
    ('wikibooks_red_devils', 10, 'Remove once the bread is toasted, the cheese is golden at the edges, and the bacon is fully cooked.')
) as v(recipe_slug, step_number, instruction)
join public.recipes r on r.slug = v.recipe_slug;

